  }
  return plan;
}

// Cambios: descarta el «Arranque» que haya mandado el modelo y pone, al comienzo de la misma fase donde estaba, el que
// está guardado (con lo que Luis haya editado en él). Si la fase no vino en la respuesta, unirPor ya dejó la guardada.
// Cambia el plan que recibe y lo devuelve.
function restituirArranque(plan, anterior) {
  const guardados = new Map();
  for (const f of (anterior && Array.isArray(anterior.fases) ? anterior.fases : [])) {
    if (!esObjetoPlano(f) || !Array.isArray(f.bloques)) continue;
    const a = f.bloques.filter(esArranque);
    if (a.length && !guardados.has(f.clave)) guardados.set(f.clave, a);
  }
  quitarArranque(plan);
  for (const f of (plan && Array.isArray(plan.fases) ? plan.fases : [])) {
    if (!esObjetoPlano(f) || !Array.isArray(f.bloques) || !guardados.has(f.clave)) continue;
    f.bloques = JSON.parse(JSON.stringify(guardados.get(f.clave))).concat(f.bloques);
    guardados.delete(f.clave);
  }
  return plan;
}

// Solo láminas del plan, una foto por lámina y el filtro de fotos_guard (idempotente: volver a filtrar una
// descripción ya filtrada no la cambia, así el renderer reutiliza la foto por su hash y no la vuelve a cobrar).
function fotosDelPlan(briefs, nFases, hayPropuesta) {
  const validas = new Set(slidesConFoto(hayPropuesta, nFases));
  const vistas = new Set();
  const elegidas = (Array.isArray(briefs) ? briefs : []).filter((b) => esObjetoPlano(b) && typeof b.slide === 'string'
    && typeof b.prompt === 'string' && b.prompt.trim() !== '' && validas.has(b.slide) && !vistas.has(b.slide)
    && vistas.add(b.slide));
  return limpiarFotos(elegidas.map((b) => ({ slide: b.slide, prompt: b.prompt }))).limpias;
}

// Cambios: una actividad se reconoce por su nombre (sin mayúsculas ni espacios de más) y por cuántas veces apareció
// antes ese nombre en el plan: la misma clave que at_pt_recorrer_actividades de WordPress (Task 2). Moverla de bloque
// no la hace nueva; renombrarla, sí (por eso el prompt le prohíbe al modelo renombrar las de Luis). Si Luis le puso
// los días a mano (origen «luis»), vuelven a los guardados aunque el modelo los haya cambiado. Una actividad que ya
// existía conserva su origen si el modelo no le cambió los días; si se los cambió, o si es nueva, queda «ia»
// (revisar), como la marca WordPress (at_pt_marcar_ediciones(…, 'ia')): el modelo nunca declara «luis» ni «tabla».
// Devuelve cuántas actividades de Luis traían días distintos.
function protegerLuis(plan, anterior) {
  const contador = () => {
    const vistas = new Map();
    return (a) => {
      const n = normPlan(a.nombre);
      vistas.set(n, (vistas.get(n) || 0) + 1);
      return n + '#' + vistas.get(n);
    };
  };
  const previas = new Map();
  const claveAnterior = contador();
  recorrerActividades(anterior, (a) => { previas.set(claveAnterior(a), a); });
  const claveNueva = contador();
  let protegidas = 0;
  recorrerActividades(plan, (a) => {
    const p = previas.get(claveNueva(a));
    if (!p) { a.origen = 'ia'; return; }
    const mismosDias = Number(a.dias_habiles) === Number(p.dias_habiles);
    if (p.origen === 'luis') {
      if (!mismosDias) protegidas++;
      a.dias_habiles = p.dias_habiles;
      a.origen = 'luis';
    } else {
      a.origen = p.origen === 'tabla' && mismosDias ? 'tabla' : 'ia';
    }
  });
  return protegidas;
}

// Une dos listas de objetos por un campo (fases por «clave», fotos por «slide»): cada elemento guardado se reemplaza,
// en su lugar, por el que trae el modelo con el mismo campo; los que el modelo agrega van al final. Si alguna de las
// dos no es una lista o el modelo la manda vacía, queda la del modelo tal cual (la validación decide).
function unirPor(antes, nuevos, campo) {
  if (nuevos === undefined) return antes;
  if (!Array.isArray(antes) || !Array.isArray(nuevos) || !nuevos.length) return nuevos;
  const dados = new Map(nuevos.filter(esObjetoPlano).map((x) => [x[campo], x]));
  const previos = antes.filter(esObjetoPlano);
  return previos.map((x) => (dados.has(x[campo]) ? dados.get(x[campo]) : x))
    .concat(nuevos.filter((x) => !esObjetoPlano(x) || !previos.some((p) => p[campo] === x[campo])));
}

// ia = salida del nodo OpenAI ({message: {content}} o {error} con onError=continue).
// op = {modo: 'borrador'|'cambios', hayPropuesta: bool, anterior: plan guardado (solo en cambios)}.
function leerPlanModelo(ia, op) {
  const mal = (reason) => ({ ok: false, reason: sinUrlInterna(reason), plan: null, protegidas: 0 });
  const contenido = ia && ia.message ? ia.message.content : null;
  if (contenido == null || String(contenido).trim() === '') {
    const err = ia && ia.error ? (ia.error.message || String(ia.error)) : '';
    return mal('El modelo no respondió' + (err ? ': ' + err : ''));
  }
  let r;
  try {
    r = leerJsonModelo(contenido);
  } catch (e) {
    return mal('La respuesta del modelo no es un JSON válido (' + (e && e.message ? e.message : String(e)) + ')');
  }
  if (!esObjetoPlano(r)) return mal('La respuesta del modelo no es un objeto JSON');
  // El modelo a veces imita la forma de la entrada y envuelve el plan: {"plan": …} o {"plan_actual": …}.
  for (const k of ['plan', 'plan_actual']) {
    if (esObjetoPlano(r[k]) && Object.keys(r).every((x) => x === k || x === 'comentarios')) { r = r[k]; break; }
  }
  // Claves que no son del plan. En cambios, una nota o un «antes/después» no pasan como cambio aplicado: toda clave
  // debe ser del plan (o una que ya traía el plan guardado). En borrador se descartan: WordPress arma el plan solo con
  // las claves que conoce, y una nota suelta o la plantilla del prompt igual fallan por no traer fases o actividades.
  const cambios = op.modo === 'cambios';
  const previo = cambios && esObjetoPlano(op.anterior) ? op.anterior : {};
  const ajenas = Object.keys(r).filter((k) => !CLAVES_PLAN.includes(k) && !Object.prototype.hasOwnProperty.call(previo, k));
  if (ajenas.length && cambios) return mal('La respuesta del modelo trae claves que no son del plan: ' + ajenas.slice(0, 5).join(', '));
  for (const k of ajenas) delete r[k];
  let plan = r;
  if (cambios) {
    if (!Object.keys(r).length) return mal('La respuesta del modelo no trae ninguna parte del plan');
    // Lo que el modelo omita se conserva del plan guardado: nunca se manda a WordPress un plan a medias. Las fases se
    // unen por su clave y las fotos por su lámina: si el modelo devuelve solo la fase o la foto que cambió, las otras
    // quedan como estaban (con los días de Luis, y cada foto con su mismo texto, que el renderer reconoce por su hash).
    plan = Object.assign({}, previo, r);
    plan.fases = unirPor(previo.fases, r.fases, 'clave');
    plan.image_briefs = unirPor(previo.image_briefs, r.image_briefs, 'slide');
  }
  plan = JSON.parse(JSON.stringify(plan));
  if (!Array.isArray(plan.fases) || !plan.fases.length) return mal('El plan del modelo no trae fases');
  if (plan.fases.some((f) => !esObjetoPlano(f) || !Array.isArray(f.bloques))) {
    return mal('El plan del modelo trae una fase sin su lista de bloques');
  }
  // El «Arranque» del modelo se descarta: en borrador lo pone WordPress; en cambios vuelve el guardado.
  if (cambios) restituirArranque(plan, previo);
  else quitarArranque(plan);
  let n = 0;
  recorrerActividades(plan, () => { n++; });
  if (!n) return mal('El modelo no propuso ninguna actividad');
  let protegidas = 0;
  if (cambios) protegidas = protegerLuis(plan, previo);
  else recorrerActividades(plan, (a) => { a.origen = 'ia'; });
  plan.image_briefs = fotosDelPlan(plan.image_briefs, plan.fases.length, op.hayPropuesta === true);
  return { ok: true, reason: '', plan, protegidas };
}


const NOMBRES_LAMINAS = { cover: 'portada', metodo: 'Método AT', gantt: 'carta Gantt', fase_1: 'fase 1', fase_2: 'fase 2',
  fase_3: 'fase 3', necesitamos: 'qué necesitamos de ti', reuniones: 'reuniones y soporte', portal: 'sigue tu proyecto',
  cierre: 'cierre' };
const nombresLaminas = (l) => (Array.isArray(l) ? l : []).map((s) => NOMBRES_LAMINAS[s] || String(s)).join(', ');

// Decisión 7: portada y cierre del plan reutilizan, sin costo, las fotos de la propuesta (cover y next_steps).
// manifest = img/manifest.json de la propuesta en el renderer ({lámina: {file, hash}}); base = URL del renderer;
// uid = unique_link_id de la propuesta. Pone la URL absoluta en render.images (el renderer la copia junto al plan y no
// genera esa foto) y, si hay propuesta, quita portada y cierre de render.image_briefs: nunca se pagan, porque el panel
// no las cuenta en el costo (at_pt_costo_fotos). Si la propuesta no tiene esa foto, la lámina va sin foto y se avisa.
// Nunca lanza y no cambia `render`: devuelve {render (copia), reutilizadas, sin_foto}.
function reutilizarFotosPlan(render, manifest, base, uid) {
  const r = JSON.parse(JSON.stringify(esObjetoPlano(render) ? render : {}));
  const images = esObjetoPlano(r.images) ? r.images : {};
  const reutilizadas = [];
  const sin_foto = [];
  if (!/^[A-Za-z0-9_-]{6,64}$/.test(String(uid || ''))) {
    r.images = images;
    return { render: r, reutilizadas, sin_foto };
  }
  let m = manifest;
  if (typeof m === 'string') { try { m = JSON.parse(m); } catch (e) { m = null; } }
  if (!esObjetoPlano(m)) m = {};
  const baseOk = /^https?:\/\/[A-Za-z0-9.-]+(:\d+)?$/.test(String(base || ''));
  for (const [lamina, dePropuesta] of Object.entries(SLIDES_DE_PROPUESTA)) {
    const e = Object.prototype.hasOwnProperty.call(m, dePropuesta) ? m[dePropuesta] : null;
    // Nombre de archivo como los que guarda el renderer (<lámina>.<ext>): sin «..», sin barras ni archivos ocultos.
    const file = esObjetoPlano(e) && typeof e.file === 'string' && /^[A-Za-z0-9_-]+\.[A-Za-z0-9]{2,5}$/.test(e.file) ? e.file : '';
    if (file && baseOk) {
      images[lamina] = base + '/p/' + uid + '/img/' + file;
      reutilizadas.push(lamina);
    } else if (!images[lamina]) {
      sin_foto.push(lamina);
    }
  }
  r.image_briefs = (Array.isArray(r.image_briefs) ? r.image_briefs : [])
    .filter((b) => !(esObjetoPlano(b) && Object.prototype.hasOwnProperty.call(SLIDES_DE_PROPUESTA, b.slide)));
  r.images = images;
  return { render: r, reutilizadas, sin_foto };
}

// Decisión D10: con el plan en uno de estos estados, una vista previa no se dibuja (pisaría la versión final en
// /p/<codigo>/). WordPress tampoco guarda sus enlaces (POST /vista, Task 7).
const ESTADOS_SIN_VISTA_PREVIA = ['aprobando', 'listo', 'enviado'];

// Salida del nodo «Render» (fullResponse + neverError): {statusCode, body, headers}; si se cortó la red o venció el
// tiempo, {error} sin statusCode (onError: continueRegularOutput). También acepta el cuerpo suelto (sin fullResponse).
// Decisión D11: se reintenta solo lo que puede salir distinto (la red, un 5xx, o un 200 sin presentación o con fotos
// faltantes). Un 4xx da lo mismo cada vez: el 400 del esquema trae sus motivos en `details` (Task 11), que van a la nota.
// Nunca lanza.
function leerRespuestaRender(x) {
  const j = esObjetoPlano(x) ? x : {};
  let status = 0;
  let cuerpo = {};
  let fallo = '';
  if (j.statusCode !== undefined && j.statusCode !== null && j.statusCode !== '') {
    status = Number(j.statusCode) || 0;
    let b = j.body;
    if (typeof b === 'string') {
      try { b = JSON.parse(b); } catch (e) { b = { error: b.slice(0, 200) }; }
    }
    cuerpo = esObjetoPlano(b) ? b : {};
  } else if (j.error) {
    const e = j.error;
    fallo = sinUrlInterna(typeof e === 'string' ? e : String(e.message || e.description || 'sin detalle'));
  } else if (Object.keys(j).length) {
    status = 200;
    cuerpo = j;
  } else {
    fallo = 'sin respuesta';
  }
  const d = cuerpo.details;
  const detalles = (Array.isArray(d) ? d : (d == null || d === '' ? [] : [d])).map((t) => sinUrlInterna(String(t).slice(0, 200))).filter(Boolean).slice(0, 5);
  const images = status === 200 && esObjetoPlano(cuerpo.images) ? cuerpo.images : {};
  const missing = Array.isArray(images.missing) ? images.missing.map(String) : [];
  const url = (u) => (status === 200 && typeof u === 'string' ? u : '');
  const view_url = url(cuerpo.view_url);
  const pdf_url = url(cuerpo.pdf_url);
  const reintentable = status === 0 || status >= 500 || (status === 200 && (!view_url || missing.length > 0));
  return { status, cuerpo, view_url, pdf_url, images, missing, detalles, fallo, reintentable };
}


const sha256 = (() => {
  const K = [];
  const H0 = [];
  const frac = (x) => ((x - Math.floor(x)) * 0x100000000) >>> 0;
  for (let n = 2; K.length < 64; n++) {
    let primo = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) { primo = false; break; }
    if (!primo) continue;
    if (H0.length < 8) H0.push(frac(Math.pow(n, 1 / 2)));
    K.push(frac(Math.pow(n, 1 / 3)));
  }
  const rot = (x, k) => (x >>> k) | (x << (32 - k));
  return (texto) => {
    const b = [];
    for (const ch of String(texto)) {
      let c = ch.codePointAt(0);
      if (c >= 0xd800 && c <= 0xdfff) c = 0xfffd;  // sustituto suelto: node lo codifica como U+FFFD
      if (c < 0x80) b.push(c);
      else if (c < 0x800) b.push(0xc0 | (c >> 6), 0x80 | (c & 63));
      else if (c < 0x10000) b.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
      else b.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    }
    const bits = b.length * 8;
    b.push(0x80);
    while (b.length % 64 !== 56) b.push(0);
    const alto = Math.floor(bits / 0x100000000);
    for (const v of [alto, bits >>> 0]) b.push((v >>> 24) & 255, (v >>> 16) & 255, (v >>> 8) & 255, v & 255);
    const H = H0.slice();
    const w = new Array(64);
    for (let i = 0; i < b.length; i += 64) {
      for (let j = 0; j < 16; j++) w[j] = (b[i + 4 * j] << 24) | (b[i + 4 * j + 1] << 16) | (b[i + 4 * j + 2] << 8) | b[i + 4 * j + 3];
      for (let j = 16; j < 64; j++) {
        const s0 = rot(w[j - 15], 7) ^ rot(w[j - 15], 18) ^ (w[j - 15] >>> 3);
        const s1 = rot(w[j - 2], 17) ^ rot(w[j - 2], 19) ^ (w[j - 2] >>> 10);
        w[j] = (w[j - 16] + s0 + w[j - 7] + s1) | 0;
      }
      let [a, bb, c, d, e, f, g, h] = H;
      for (let j = 0; j < 64; j++) {
        const t1 = (h + (rot(e, 6) ^ rot(e, 11) ^ rot(e, 25)) + ((e & f) ^ (~e & g)) + K[j] + w[j]) | 0;
        const t2 = ((rot(a, 2) ^ rot(a, 13) ^ rot(a, 22)) + ((a & bb) ^ (a & c) ^ (bb & c))) | 0;
        h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = bb; bb = a; a = (t1 + t2) | 0;
      }
      [a, bb, c, d, e, f, g, h].forEach((v, k) => { H[k] = (H[k] + v) | 0; });
    }
    return H.map((v) => (v >>> 0).toString(16).padStart(8, '0')).join('');
  };
})();

const RETOMA = ", clean photograph with no written characters anywhere in the frame: no subtitles, no captions, no signs, no papers with writing or drawings";
const INSTRUCCION_TEXTO = "You are checking photos for a sales presentation. Report every photo in which ANY written characters are visible: letters, words, numbers, subtitles or captions over the image, signs, labels, stickers, papers or screens with writing, or scribbles that look like writing, even if small, blurred or illegible. Ignore plain shapes, patterns and wood grain. Answer ONLY with JSON {\"con_texto\": [\"<photo name>\", ...]} using the photo names given; use [] if no photo has text.";

// Una foto rehecha por texto en una corrida anterior quedó en el renderer con la descripción + RETOMA, pero WordPress
// guarda solo la original. Si el manifest del plan (/p/<codigo>/img/manifest.json) tiene para esa lámina el sha256 de
// «original + RETOMA», se pide esa descripción y el renderer reutiliza la foto limpia en vez de pagar otra (que podría
// volver a salir con texto). Una lámina que cambió no calza y se genera como siempre. Va DESPUÉS de fotosDelPlan: el
// filtro de fotos_guard descarta una descripción con RETOMA («papers», «drawings»). Nunca lanza; no cambia `briefs`.
function retomasPrevias(briefs, manifest) {
  let m = manifest;
  if (typeof m === 'string') { try { m = JSON.parse(m); } catch (e) { m = null; } }
  if (!esObjetoPlano(m)) m = {};
  const retomadas = [];
  const salida = (Array.isArray(briefs) ? briefs : []).map((b) => {
    if (!esObjetoPlano(b) || typeof b.prompt !== 'string' || b.prompt.endsWith(RETOMA)) return b;
    const e = Object.prototype.hasOwnProperty.call(m, b.slide) ? m[b.slide] : null;
    if (esObjetoPlano(e) && typeof e.hash === 'string' && e.hash === sha256(b.prompt + RETOMA)) {
      retomadas.push(b.slide);
      return { slide: b.slide, prompt: b.prompt + RETOMA };
    }
    return b;
  });
  return { briefs: salida, retomadas };
}

// Fotos que se le muestran a GPT-4o: las pedidas en esta versión (image_briefs, nunca la portada ni el cierre que vienen
// de la propuesta), guardadas junto al plan según su manifest y que salieron en el último render (ni faltantes ni
// enlazadas afuera: el manifest conserva la entrada vieja de una foto que esta vez no salió, y esa no está en el
// documento). Solo archivos <lámina>.<ext> como los guarda el renderer: sin «..», barras ni archivos ocultos. ?v=
// cambia en cada render: la foto rehecha se guarda con el MISMO nombre y así nadie entrega una copia guardada.
function fotosParaRevisar(pedidas, manifest, images, uid, base, v) {
  const m = esObjetoPlano(manifest) ? manifest : {};
  const img = esObjetoPlano(images) ? images : {};
  const fuera = new Set([...(Array.isArray(img.missing) ? img.missing : []), ...(Array.isArray(img.kept_remote) ? img.kept_remote : [])].map(String));
  if (!/^[A-Za-z0-9_-]{6,64}$/.test(String(uid || '')) || !/^https?:\/\/[A-Za-z0-9.-]+(:\d+)?$/.test(String(base || ''))) return [];
  const vistas = new Set();
  return (Array.isArray(pedidas) ? pedidas : []).map(String).filter((s) => {
    if (vistas.has(s) || fuera.has(s) || !Object.prototype.hasOwnProperty.call(m, s)) return false;
    vistas.add(s);
    const e = m[s];
    return esObjetoPlano(e) && typeof e.file === 'string' && /^[A-Za-z0-9_-]+\.[A-Za-z0-9]{2,5}$/.test(e.file);
  }).map((s) => ({ slide: s, url: base + '/p/' + uid + '/img/' + m[s].file + '?v=' + (Number(v) || 0) }));
}

// UNA consulta con todas las fotos (la misma forma que «3 Final» de las propuestas): gpt-4o, temperatura 0, JSON.
function cuerpoRevision(fotos) {
  const contenido = [{ type: 'text', text: INSTRUCCION_TEXTO }];
  for (const f of fotos) {
    contenido.push({ type: 'text', text: 'Photo "' + f.slide + '":' });
    contenido.push({ type: 'image_url', image_url: { url: f.url, detail: 'high' } });
  }
  return { model: 'gpt-4o', temperature: 0, max_tokens: 200, response_format: { type: 'json_object' },
    messages: [{ role: 'user', content: contenido }] };
}

// Salida del nodo «Buscar texto en fotos» (fullResponse + neverError; {error} si se cortó la red). Devuelve las láminas
// con texto, sin repetidas y solo entre las que se le mostraron al modelo, o null con el motivo de la falla. Nunca lanza.
function leerRevision(r, mostradas) {
  const x = esObjetoPlano(r) ? r : {};
  if (x.statusCode !== 200) {
    const e = x.error;
    const msg = e && typeof e === 'object' ? e.message : e;
    return { con_texto: null, fallo: x.statusCode ? 'OpenAI respondió HTTP ' + x.statusCode : 'OpenAI no respondió' + (msg ? ': ' + sinUrlInterna(String(msg).slice(0, 200)) : '') };
  }
  try {
    const j = JSON.parse(x.body.choices[0].message.content);
    if (!esObjetoPlano(j) || !Array.isArray(j.con_texto)) throw new Error('sin con_texto');
    const l = Array.isArray(mostradas) ? mostradas : [];
    return { con_texto: [...new Set(j.con_texto.map(String))].filter((s) => l.includes(s)), fallo: '' };
  } catch (e) {
    return { con_texto: null, fallo: 'respuesta ilegible del modelo' };
  }
}

const RENDERER_BASE = "https://n8n-propuesta-renderer.kchiba.easypanel.host";
const MAX_RENDERS = 3;
// Tras cada render: en la versión final se vuelve a llamar al renderer solo si puede salir distinto (D11): la red o
// el tiempo, un 5xx, o un 200 sin presentación o con fotos faltantes. Un 4xx (el 400 del esquema con details) da lo
// mismo cada vez: no se reintenta. El renderer reutiliza las fotos ya guardadas con el mismo prompt
// (img/manifest.json del plan) y solo pide las que faltan: un reintento no vuelve a pagar las que ya salieron.
// Tope: MAX_RENDERS llamadas EN TOTAL, contando la retoma por texto (D18): si «Decidir retoma» pidió rehacer fotos,
// los reintentos siguen con SUS descripciones (con las originales, el renderer volvería a pedir la foto con texto).
// La revisión de texto corre solo con la versión final completa (presentación y todas las fotos): si faltan fotos,
// el plan queda en «error» y la revisión corre cuando Luis lo apruebe de nuevo. Nunca lanza.
const retoma = $('Decidir retoma').isExecuted && $('Decidir retoma').first().json.rehacer === true;
const base = retoma ? $('Decidir retoma').first().json : $('Preparar render').first().json;
const r = $input.first().json || {};
const intento = $runIndex + 1;
const lr = leerRespuestaRender(r);
const final = base.modo === 'final';
return [{ json: Object.assign({}, base, { resultado: r, intento,
  reintentar: final && lr.reintentable && intento < MAX_RENDERS,
  revisar_texto: final && lr.status === 200 && !!lr.view_url && lr.missing.length === 0 }) }];

const CLAVES_PROPUESTA = ['client_name', 'company_name', 'challenge_title', 'challenge_text', 'solution_title', 'solution_text',
  'benefits', 'how_it_works', 'extra_slides', 'pricing_rows', 'pricing_note', 'next_steps', 'correo_cliente', 'image_briefs', 'unique_id'];
function esObjetoPlano(v) { return v !== null && typeof v === 'object' && !Array.isArray(v); }
function leerJsonModelo(raw) {
  if (raw !== null && typeof raw === 'object') return raw;
  const s = String(raw == null ? '' : raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try {
    return JSON.parse(s);
  } catch (error) {
    // Única tolerancia: llaves «}» de más después de un objeto completo (ejecución 408862).
    if (s[0] === '{') {
      let prof = 0, enTexto = false, escape = false, fin = -1;
      for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (enTexto) {
          if (escape) escape = false;
          else if (ch === '\\') escape = true;
          else if (ch === '"') enTexto = false;
          continue;
        }
        if (ch === '"') enTexto = true;
        else if (ch === '{') prof++;
        else if (ch === '}') { prof--; if (prof === 0) { fin = i; break; } }
      }
      if (fin > 0 && /^[\s}]*$/.test(s.slice(fin + 1))) return JSON.parse(s.slice(0, fin + 1));
    }
    throw error;
  }
}


const PROHIBIDO = /\b(websites?|web ?pages?|web ?design|interfaces?|dashboards?|apps?|charts?|graphs?|flow ?charts?|diagrams?|infographics?|whiteboards?|spreadsheets?|clipboards?|checklists?|documents?|paperwork|printed|forms?|signs?|signage|posters?|banners?|billboards?|scoreboards?|menus?|newspapers?|magazines?|catalogu?e?s?|brochures?|flyers?|receipts?|invoices?|price tags?|calendars?|notebooks?|notepads?|project plans?|business plans?|plans? on|sketch(?:es)?|blueprints?|(?:technical|architectural|pencil) drawings?|drawings? on (?:paper|a sheet)|drawings|(?:assembly|written|printed|step-by-step) instructions|instruction (?:sheets?|manuals?|booklets?|leaflets?|cards?)|reading (?:the )?instructions|(?:user|owner'?s|assembly|training) manuals?|manuals|papers|sheets? of paper|paper sheets?|pieces? of paper|sticky notes?|post-?its?|text|letters?|lettering|words?|numbers?|meetings?|office)\b/i;
// Dibujos, instrucciones y manuales cuentan solo como PAPEL (2026-09-27): el singular calza con verbos y adjetivos
// de escenas del rubro sin papel ("nurse drawing blood", "manual therapy", "coach giving instructions to kids").
// El plural «drawings» y «manuals» queda prohibido porque casi siempre es el sustantivo (hojas con garabatos).
const CON_ETIQUETA =/\b(screens?|monitors?|displays?|laptops?|computers?|tablets?|phones?|smartphones?|cell ?phones?|bottles?|cans?|box(?:es)?|packag\w*|books?|labels?|shelves|shelf|jerseys?|t-?shirts?)\b/i;
// Solo cuenta lo que neutraliza al PRODUCTO. "blurred background" desenfoca el fondo, no la etiqueta
// (botillería de prueba 49, 2026-09-24: "wine bottle ... blurred background" habría salido con etiqueta nítida).
const NEUTRALIZADO = /(facing away|closed|turned off|switched off|dark screen|screen off|unlabell?ed|without (a |any )?labels?|plain|blank|from behind|seen from the back)/i;
const FONDO_PORTADA = /\b(stadiums?|facades?|storefronts?|shop ?fronts?|exteriors?|buildings?|streets?|walls?|billboards?|bleachers?|grandstands?)\b/i;
// Tiendas (2026-09-26): el fondo con góndolas y letreros trae texto (beneficios de la 53, en un supermercado). Se
// conserva la escena del rubro, en primer plano con el fondo desenfocado, igual que la portada.
const TIENDA = /\b(stores?|shops?|supermarkets?|markets?|malls?|aisles?|showrooms?|boutiques?|warehouses?|retail)\b/i;
const PRIMER_PLANO =/(close-?up|macro|shallow depth of field|bokeh|blurred background|background (completely )?blurred)/i;
// «no subtitles, no captions» (2026-09-26): en la propuesta 53 salieron leyendas blancas inventadas al centro abajo,
// como subtítulos de película.
const CIERRE = 'no signs, no labels, no text, no lettering, no logos, no watermarks, no subtitles, no captions';
const NEGATIVAS = /[,.;]?\s*\b(?:no|without)\b(?:\s+any)?[^,.;]*?\b(?:people facing camera|screens?|signs?|signage|labels?|text|lettering|logos?|words?|watermarks?|writing|subtitles?|captions?)\b[^,.;]*/gi;
const SEGURAS = {
  cover: 'close-up of warm morning light falling across a textured wooden surface with a small green plant, background completely blurred into soft golden bokeh, shallow depth of field',
  challenge: 'quiet empty room at night lit by a single warm lamp, rain drops on a large window, calm pensive mood',
  solution: 'bright calm space with natural light through tall windows and a green plant, soft morning light',
  benefits: 'wide open landscape of the Chilean central valley at sunrise with the Andes in the distance, soft golden light',
  how_it_works: 'close-up of hands arranging small wooden blocks in a neat row on a light table, soft daylight, shallow depth of field',
  pricing: 'close-up of a single green sprout growing from rich dark soil in soft morning light, shallow depth of field',
  next_steps: 'open country road through green hills at sunrise, soft mist, hopeful calm atmosphere',
  extra: 'soft pattern of light and shadow on a textured surface next to a small plant, calm minimal composition',
};
// GPT-4o escribe escenas del rubro ("hand holding a wine bottle") pero no agrega "sin etiqueta" aunque se le
// pida (Borrador 403817, 2026-09-24). En vez de perder la escena, el filtro la neutraliza: producto sin etiqueta,
// pantallas apagadas y de espaldas. Si aun así queda algo sin neutralizar, se reemplaza.
const PRODUCTO = /\b((?:(?:wine|beer|liquor|whisky|whiskey|pisco|vodka|gin|rum|glass|plastic|cardboard|gift|delivery)\s+)?(?:bottles?|cans?|jars?|box(?:es)?|packages?|parcels?|books?|jerseys?|t-?shirts?))\b/gi;
const PANTALLA = /\b(screens?|monitors?|displays?|laptops?|computers?|tablets?|phones?|smartphones?|cell ?phones?)\b/i;
function neutralizar(tema) {
  if (!CON_ETIQUETA.test(tema) || NEUTRALIZADO.test(tema)) return tema;
  let t = tema.replace(/\s*with (?:its|a|the|their) labels?/gi, '').replace(PRODUCTO, 'plain unlabeled $1');
  if (PANTALLA.test(t)) t += ', every screen dark and facing away from the camera';
  if (/\b(shelves|shelf)\b/i.test(t) && !/unlabell?ed/i.test(t)) t += ', shelves holding only plain unlabeled products';
  return t;
}
function motivoFoto(slide, tema) {
  if (!tema) return 'vacía';
  if (PROHIBIDO.test(tema)) return 'texto o pantalla';
  if (slide === 'cover' && FONDO_PORTADA.test(tema)) return 'portada con estructuras de fondo';
  if (CON_ETIQUETA.test(tema) && !NEUTRALIZADO.test(tema)) return 'producto con etiqueta o pantalla visible';
  return '';
}
function limpiarFotos(briefs) {
  let reemplazadas = 0;
  let neutralizadas = 0;
  const limpias = (briefs || []).filter((b) => b && b.slide).map((b) => {
    // Se descarta la lista de prohibiciones que haya escrito el modelo: el cierre lo pone siempre el filtro.
    // Cualquier forma: ", no text", ". No signs", "without any text or signage" (revisión final 2026-09-24, M5:
    // antes solo se cortaba ", no …" y una escena buena caía en PROHIBIDO por su propia prohibición).
    const original = String(b.prompt || '').replace(NEGATIVAS, '').trim().replace(/[\s,.;]+$/, '');
    let tema = neutralizar(original);
    if (motivoFoto(b.slide, tema)) {
      reemplazadas++;
      tema = SEGURAS[b.slide] || SEGURAS.extra;
    } else if (tema !== original) {
      neutralizadas++;
    }
    if ((b.slide === 'cover' || TIENDA.test(tema)) && !PRIMER_PLANO.test(tema)) {
      tema += ', close-up, shallow depth of field, background completely blurred';
    }
    return { slide: b.slide, prompt: `${tema}, ${CIERRE}` };
  });
  return { limpias, reemplazadas, neutralizadas };
}


// Un mensaje de red de n8n puede traer la URL del servidor y el SMTP de Hostinger rechaza (554 5.7.1) un correo que
// lleve un enlace al servidor de Easypanel. Cambia toda URL o nombre de servidor de ese dominio por «(servidor interno)».
// Se usa en los tres flujos, sobre todo mensaje de error antes de armar la nota que guarda WordPress y el correo a Luis.
// El nombre del dominio va partido a propósito: ninguna prueba ni el código de un correo puede llevarlo escrito entero.
const SERVIDOR_INTERNO = new RegExp('\\S*easy' + 'panel\\.host\\S*', 'gi');
const sinUrlInterna = (t) => String(t == null ? '' : t).replace(SERVIDOR_INTERNO, '(servidor interno)');

const CLAVES_PLAN = ['version', 'proyecto', 'fecha_firma', 'fecha_inicio', 'fases', 'hitos', 'necesitamos_de_ti',
  'reuniones', 'soporte', 'image_briefs', 'cronograma'];
// Láminas con foto NUEVA (decisión 7). Portada y cierre solo si el contrato no tiene propuesta: si la tiene,
// se reutilizan sus fotos (portada ← cover, cierre ← next_steps) y no se pagan.
const SLIDES_NUEVAS = ['metodo', 'gantt', 'fase_1', 'fase_2', 'fase_3', 'necesitamos', 'reuniones', 'portal'];
const SLIDES_DE_PROPUESTA = { cover: 'cover', cierre: 'next_steps' };
const normPlan = (s) => String(s == null ? '' : s).trim().toLowerCase().replace(/\s+/g, ' ');

function slidesConFoto(hayPropuesta, nFases) {
  const n = Math.max(0, Math.min(3, Number(nFases) || 0));
  const l = SLIDES_NUEVAS.filter((s) => !/^fase_\d$/.test(s) || Number(s.slice(5)) <= n);
  return hayPropuesta ? l : ['cover', ...l, 'cierre'];
}

function recorrerActividades(plan, fn) {
  const fases = plan && Array.isArray(plan.fases) ? plan.fases : [];
  for (const f of fases) {
    if (!esObjetoPlano(f) || !Array.isArray(f.bloques)) continue;
    for (const b of f.bloques) {
      if (!esObjetoPlano(b) || !Array.isArray(b.actividades)) continue;
      for (const a of b.actividades) if (esObjetoPlano(a)) fn(a, b, f);
    }
  }
}

// El bloque «Arranque» (reunión de inicio y entrega de logo, textos y accesos) lo pone WordPress (at_pt_arranque, con
// los días de la tabla) y Luis lo puede editar en el panel: el modelo nunca lo manda ni lo cambia (decisión D12).
const esArranque = (b) => esObjetoPlano(b) && normPlan(b.nombre) === 'arranque';

// Saca los bloques «Arranque» de todas las fases. Cambia el plan que recibe y lo devuelve.
function quitarArranque(plan) {
  for (const f of (plan && Array.isArray(plan.fases) ? plan.fases : [])) {
    if (esObjetoPlano(f) && Array.isArray(f.bloques)) f.bloques = f.bloques.filter((b) => !esArranque(b));
  }
  return plan;
}

// Cambios: descarta el «Arranque» que haya mandado el modelo y pone, al comienzo de la misma fase donde estaba, el que
// está guardado (con lo que Luis haya editado en él). Si la fase no vino en la respuesta, unirPor ya dejó la guardada.
// Cambia el plan que recibe y lo devuelve.
function restituirArranque(plan, anterior) {
  const guardados = new Map();
  for (const f of (anterior && Array.isArray(anterior.fases) ? anterior.fases : [])) {
    if (!esObjetoPlano(f) || !Array.isArray(f.bloques)) continue;
    const a = f.bloques.filter(esArranque);
    if (a.length && !guardados.has(f.clave)) guardados.set(f.clave, a);
  }
  quitarArranque(plan);
  for (const f of (plan && Array.isArray(plan.fases) ? plan.fases : [])) {
    if (!esObjetoPlano(f) || !Array.isArray(f.bloques) || !guardados.has(f.clave)) continue;
    f.bloques = JSON.parse(JSON.stringify(guardados.get(f.clave))).concat(f.bloques);
    guardados.delete(f.clave);
  }
  return plan;
}

// Solo láminas del plan, una foto por lámina y el filtro de fotos_guard (idempotente: volver a filtrar una
// descripción ya filtrada no la cambia, así el renderer reutiliza la foto por su hash y no la vuelve a cobrar).
function fotosDelPlan(briefs, nFases, hayPropuesta) {
  const validas = new Set(slidesConFoto(hayPropuesta, nFases));
  const vistas = new Set();
  const elegidas = (Array.isArray(briefs) ? briefs : []).filter((b) => esObjetoPlano(b) && typeof b.slide === 'string'
    && typeof b.prompt === 'string' && b.prompt.trim() !== '' && validas.has(b.slide) && !vistas.has(b.slide)
    && vistas.add(b.slide));
  return limpiarFotos(elegidas.map((b) => ({ slide: b.slide, prompt: b.prompt }))).limpias;
}

// Cambios: una actividad se reconoce por su nombre (sin mayúsculas ni espacios de más) y por cuántas veces apareció
// antes ese nombre en el plan: la misma clave que at_pt_recorrer_actividades de WordPress (Task 2). Moverla de bloque
// no la hace nueva; renombrarla, sí (por eso el prompt le prohíbe al modelo renombrar las de Luis). Si Luis le puso
// los días a mano (origen «luis»), vuelven a los guardados aunque el modelo los haya cambiado. Una actividad que ya
// existía conserva su origen si el modelo no le cambió los días; si se los cambió, o si es nueva, queda «ia»
// (revisar), como la marca WordPress (at_pt_marcar_ediciones(…, 'ia')): el modelo nunca declara «luis» ni «tabla».
// Devuelve cuántas actividades de Luis traían días distintos.
function protegerLuis(plan, anterior) {
  const contador = () => {
    const vistas = new Map();
    return (a) => {
      const n = normPlan(a.nombre);
      vistas.set(n, (vistas.get(n) || 0) + 1);
      return n + '#' + vistas.get(n);
    };
  };
  const previas = new Map();
  const claveAnterior = contador();
  recorrerActividades(anterior, (a) => { previas.set(claveAnterior(a), a); });
  const claveNueva = contador();
  let protegidas = 0;
  recorrerActividades(plan, (a) => {
    const p = previas.get(claveNueva(a));
    if (!p) { a.origen = 'ia'; return; }
    const mismosDias = Number(a.dias_habiles) === Number(p.dias_habiles);
    if (p.origen === 'luis') {
      if (!mismosDias) protegidas++;
      a.dias_habiles = p.dias_habiles;
      a.origen = 'luis';
    } else {
      a.origen = p.origen === 'tabla' && mismosDias ? 'tabla' : 'ia';
    }
  });
  return protegidas;
}

// Une dos listas de objetos por un campo (fases por «clave», fotos por «slide»): cada elemento guardado se reemplaza,
// en su lugar, por el que trae el modelo con el mismo campo; los que el modelo agrega van al final. Si alguna de las
// dos no es una lista o el modelo la manda vacía, queda la del modelo tal cual (la validación decide).
function unirPor(antes, nuevos, campo) {
  if (nuevos === undefined) return antes;
  if (!Array.isArray(antes) || !Array.isArray(nuevos) || !nuevos.length) return nuevos;
  const dados = new Map(nuevos.filter(esObjetoPlano).map((x) => [x[campo], x]));
  const previos = antes.filter(esObjetoPlano);
  return previos.map((x) => (dados.has(x[campo]) ? dados.get(x[campo]) : x))
    .concat(nuevos.filter((x) => !esObjetoPlano(x) || !previos.some((p) => p[campo] === x[campo])));
}

// ia = salida del nodo OpenAI ({message: {content}} o {error} con onError=continue).
// op = {modo: 'borrador'|'cambios', hayPropuesta: bool, anterior: plan guardado (solo en cambios)}.
function leerPlanModelo(ia, op) {
  const mal = (reason) => ({ ok: false, reason: sinUrlInterna(reason), plan: null, protegidas: 0 });
  const contenido = ia && ia.message ? ia.message.content : null;
  if (contenido == null || String(contenido).trim() === '') {
    const err = ia && ia.error ? (ia.error.message || String(ia.error)) : '';
    return mal('El modelo no respondió' + (err ? ': ' + err : ''));
  }
  let r;
  try {
    r = leerJsonModelo(contenido);
  } catch (e) {
    return mal('La respuesta del modelo no es un JSON válido (' + (e && e.message ? e.message : String(e)) + ')');
  }
  if (!esObjetoPlano(r)) return mal('La respuesta del modelo no es un objeto JSON');
  // El modelo a veces imita la forma de la entrada y envuelve el plan: {"plan": …} o {"plan_actual": …}.
  for (const k of ['plan', 'plan_actual']) {
    if (esObjetoPlano(r[k]) && Object.keys(r).every((x) => x === k || x === 'comentarios')) { r = r[k]; break; }
  }
  // Claves que no son del plan. En cambios, una nota o un «antes/después» no pasan como cambio aplicado: toda clave
  // debe ser del plan (o una que ya traía el plan guardado). En borrador se descartan: WordPress arma el plan solo con
  // las claves que conoce, y una nota suelta o la plantilla del prompt igual fallan por no traer fases o actividades.
  const cambios = op.modo === 'cambios';
  const previo = cambios && esObjetoPlano(op.anterior) ? op.anterior : {};
  const ajenas = Object.keys(r).filter((k) => !CLAVES_PLAN.includes(k) && !Object.prototype.hasOwnProperty.call(previo, k));
  if (ajenas.length && cambios) return mal('La respuesta del modelo trae claves que no son del plan: ' + ajenas.slice(0, 5).join(', '));
  for (const k of ajenas) delete r[k];
  let plan = r;
  if (cambios) {
    if (!Object.keys(r).length) return mal('La respuesta del modelo no trae ninguna parte del plan');
    // Lo que el modelo omita se conserva del plan guardado: nunca se manda a WordPress un plan a medias. Las fases se
    // unen por su clave y las fotos por su lámina: si el modelo devuelve solo la fase o la foto que cambió, las otras
    // quedan como estaban (con los días de Luis, y cada foto con su mismo texto, que el renderer reconoce por su hash).
    plan = Object.assign({}, previo, r);
    plan.fases = unirPor(previo.fases, r.fases, 'clave');
    plan.image_briefs = unirPor(previo.image_briefs, r.image_briefs, 'slide');
  }
  plan = JSON.parse(JSON.stringify(plan));
  if (!Array.isArray(plan.fases) || !plan.fases.length) return mal('El plan del modelo no trae fases');
  if (plan.fases.some((f) => !esObjetoPlano(f) || !Array.isArray(f.bloques))) {
    return mal('El plan del modelo trae una fase sin su lista de bloques');
  }
  // El «Arranque» del modelo se descarta: en borrador lo pone WordPress; en cambios vuelve el guardado.
  if (cambios) restituirArranque(plan, previo);
  else quitarArranque(plan);
  let n = 0;
  recorrerActividades(plan, () => { n++; });
  if (!n) return mal('El modelo no propuso ninguna actividad');
  let protegidas = 0;
  if (cambios) protegidas = protegerLuis(plan, previo);
  else recorrerActividades(plan, (a) => { a.origen = 'ia'; });
  plan.image_briefs = fotosDelPlan(plan.image_briefs, plan.fases.length, op.hayPropuesta === true);
  return { ok: true, reason: '', plan, protegidas };
}


const NOMBRES_LAMINAS = { cover: 'portada', metodo: 'Método AT', gantt: 'carta Gantt', fase_1: 'fase 1', fase_2: 'fase 2',
  fase_3: 'fase 3', necesitamos: 'qué necesitamos de ti', reuniones: 'reuniones y soporte', portal: 'sigue tu proyecto',
  cierre: 'cierre' };
const nombresLaminas = (l) => (Array.isArray(l) ? l : []).map((s) => NOMBRES_LAMINAS[s] || String(s)).join(', ');

// Decisión 7: portada y cierre del plan reutilizan, sin costo, las fotos de la propuesta (cover y next_steps).
// manifest = img/manifest.json de la propuesta en el renderer ({lámina: {file, hash}}); base = URL del renderer;
// uid = unique_link_id de la propuesta. Pone la URL absoluta en render.images (el renderer la copia junto al plan y no
// genera esa foto) y, si hay propuesta, quita portada y cierre de render.image_briefs: nunca se pagan, porque el panel
// no las cuenta en el costo (at_pt_costo_fotos). Si la propuesta no tiene esa foto, la lámina va sin foto y se avisa.
// Nunca lanza y no cambia `render`: devuelve {render (copia), reutilizadas, sin_foto}.
function reutilizarFotosPlan(render, manifest, base, uid) {
  const r = JSON.parse(JSON.stringify(esObjetoPlano(render) ? render : {}));
  const images = esObjetoPlano(r.images) ? r.images : {};
  const reutilizadas = [];
  const sin_foto = [];
  if (!/^[A-Za-z0-9_-]{6,64}$/.test(String(uid || ''))) {
    r.images = images;
    return { render: r, reutilizadas, sin_foto };
  }
  let m = manifest;
  if (typeof m === 'string') { try { m = JSON.parse(m); } catch (e) { m = null; } }
  if (!esObjetoPlano(m)) m = {};
  const baseOk = /^https?:\/\/[A-Za-z0-9.-]+(:\d+)?$/.test(String(base || ''));
  for (const [lamina, dePropuesta] of Object.entries(SLIDES_DE_PROPUESTA)) {
    const e = Object.prototype.hasOwnProperty.call(m, dePropuesta) ? m[dePropuesta] : null;
    // Nombre de archivo como los que guarda el renderer (<lámina>.<ext>): sin «..», sin barras ni archivos ocultos.
    const file = esObjetoPlano(e) && typeof e.file === 'string' && /^[A-Za-z0-9_-]+\.[A-Za-z0-9]{2,5}$/.test(e.file) ? e.file : '';
    if (file && baseOk) {
      images[lamina] = base + '/p/' + uid + '/img/' + file;
      reutilizadas.push(lamina);
    } else if (!images[lamina]) {
      sin_foto.push(lamina);
    }
  }
  r.image_briefs = (Array.isArray(r.image_briefs) ? r.image_briefs : [])
    .filter((b) => !(esObjetoPlano(b) && Object.prototype.hasOwnProperty.call(SLIDES_DE_PROPUESTA, b.slide)));
  r.images = images;
  return { render: r, reutilizadas, sin_foto };
}

// Decisión D10: con el plan en uno de estos estados, una vista previa no se dibuja (pisaría la versión final en
// /p/<codigo>/). WordPress tampoco guarda sus enlaces (POST /vista, Task 7).
const ESTADOS_SIN_VISTA_PREVIA = ['aprobando', 'listo', 'enviado'];

// Salida del nodo «Render» (fullResponse + neverError): {statusCode, body, headers}; si se cortó la red o venció el
// tiempo, {error} sin statusCode (onError: continueRegularOutput). También acepta el cuerpo suelto (sin fullResponse).
// Decisión D11: se reintenta solo lo que puede salir distinto (la red, un 5xx, o un 200 sin presentación o con fotos
// faltantes). Un 4xx da lo mismo cada vez: el 400 del esquema trae sus motivos en `details` (Task 11), que van a la nota.
// Nunca lanza.
function leerRespuestaRender(x) {
  const j = esObjetoPlano(x) ? x : {};
  let status = 0;
  let cuerpo = {};
  let fallo = '';
  if (j.statusCode !== undefined && j.statusCode !== null && j.statusCode !== '') {
    status = Number(j.statusCode) || 0;
    let b = j.body;
    if (typeof b === 'string') {
      try { b = JSON.parse(b); } catch (e) { b = { error: b.slice(0, 200) }; }
    }
    cuerpo = esObjetoPlano(b) ? b : {};
  } else if (j.error) {
    const e = j.error;
    fallo = sinUrlInterna(typeof e === 'string' ? e : String(e.message || e.description || 'sin detalle'));
  } else if (Object.keys(j).length) {
    status = 200;
    cuerpo = j;
  } else {
    fallo = 'sin respuesta';
  }
  const d = cuerpo.details;
  const detalles = (Array.isArray(d) ? d : (d == null || d === '' ? [] : [d])).map((t) => sinUrlInterna(String(t).slice(0, 200))).filter(Boolean).slice(0, 5);
  const images = status === 200 && esObjetoPlano(cuerpo.images) ? cuerpo.images : {};
  const missing = Array.isArray(images.missing) ? images.missing.map(String) : [];
  const url = (u) => (status === 200 && typeof u === 'string' ? u : '');
  const view_url = url(cuerpo.view_url);
  const pdf_url = url(cuerpo.pdf_url);
  const reintentable = status === 0 || status >= 500 || (status === 200 && (!view_url || missing.length > 0));
  return { status, cuerpo, view_url, pdf_url, images, missing, detalles, fallo, reintentable };
}


const sha256 = (() => {
  const K = [];
  const H0 = [];
  const frac = (x) => ((x - Math.floor(x)) * 0x100000000) >>> 0;
  for (let n = 2; K.length < 64; n++) {
    let primo = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) { primo = false; break; }
    if (!primo) continue;
    if (H0.length < 8) H0.push(frac(Math.pow(n, 1 / 2)));
    K.push(frac(Math.pow(n, 1 / 3)));
  }
  const rot = (x, k) => (x >>> k) | (x << (32 - k));
  return (texto) => {
    const b = [];
    for (const ch of String(texto)) {
      let c = ch.codePointAt(0);
      if (c >= 0xd800 && c <= 0xdfff) c = 0xfffd;  // sustituto suelto: node lo codifica como U+FFFD
      if (c < 0x80) b.push(c);
      else if (c < 0x800) b.push(0xc0 | (c >> 6), 0x80 | (c & 63));
      else if (c < 0x10000) b.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
      else b.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    }
    const bits = b.length * 8;
    b.push(0x80);
    while (b.length % 64 !== 56) b.push(0);
    const alto = Math.floor(bits / 0x100000000);
    for (const v of [alto, bits >>> 0]) b.push((v >>> 24) & 255, (v >>> 16) & 255, (v >>> 8) & 255, v & 255);
    const H = H0.slice();
    const w = new Array(64);
    for (let i = 0; i < b.length; i += 64) {
      for (let j = 0; j < 16; j++) w[j] = (b[i + 4 * j] << 24) | (b[i + 4 * j + 1] << 16) | (b[i + 4 * j + 2] << 8) | b[i + 4 * j + 3];
      for (let j = 16; j < 64; j++) {
        const s0 = rot(w[j - 15], 7) ^ rot(w[j - 15], 18) ^ (w[j - 15] >>> 3);
        const s1 = rot(w[j - 2], 17) ^ rot(w[j - 2], 19) ^ (w[j - 2] >>> 10);
        w[j] = (w[j - 16] + s0 + w[j - 7] + s1) | 0;
      }
      let [a, bb, c, d, e, f, g, h] = H;
      for (let j = 0; j < 64; j++) {
        const t1 = (h + (rot(e, 6) ^ rot(e, 11) ^ rot(e, 25)) + ((e & f) ^ (~e & g)) + K[j] + w[j]) | 0;
        const t2 = ((rot(a, 2) ^ rot(a, 13) ^ rot(a, 22)) + ((a & bb) ^ (a & c) ^ (bb & c))) | 0;
        h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = bb; bb = a; a = (t1 + t2) | 0;
      }
      [a, bb, c, d, e, f, g, h].forEach((v, k) => { H[k] = (H[k] + v) | 0; });
    }
    return H.map((v) => (v >>> 0).toString(16).padStart(8, '0')).join('');
  };
})();

const RETOMA = ", clean photograph with no written characters anywhere in the frame: no subtitles, no captions, no signs, no papers with writing or drawings";
const INSTRUCCION_TEXTO = "You are checking photos for a sales presentation. Report every photo in which ANY written characters are visible: letters, words, numbers, subtitles or captions over the image, signs, labels, stickers, papers or screens with writing, or scribbles that look like writing, even if small, blurred or illegible. Ignore plain shapes, patterns and wood grain. Answer ONLY with JSON {\"con_texto\": [\"<photo name>\", ...]} using the photo names given; use [] if no photo has text.";

// Una foto rehecha por texto en una corrida anterior quedó en el renderer con la descripción + RETOMA, pero WordPress
// guarda solo la original. Si el manifest del plan (/p/<codigo>/img/manifest.json) tiene para esa lámina el sha256 de
// «original + RETOMA», se pide esa descripción y el renderer reutiliza la foto limpia en vez de pagar otra (que podría
// volver a salir con texto). Una lámina que cambió no calza y se genera como siempre. Va DESPUÉS de fotosDelPlan: el
// filtro de fotos_guard descarta una descripción con RETOMA («papers», «drawings»). Nunca lanza; no cambia `briefs`.
function retomasPrevias(briefs, manifest) {
  let m = manifest;
  if (typeof m === 'string') { try { m = JSON.parse(m); } catch (e) { m = null; } }
  if (!esObjetoPlano(m)) m = {};
  const retomadas = [];
  const salida = (Array.isArray(briefs) ? briefs : []).map((b) => {
    if (!esObjetoPlano(b) || typeof b.prompt !== 'string' || b.prompt.endsWith(RETOMA)) return b;
    const e = Object.prototype.hasOwnProperty.call(m, b.slide) ? m[b.slide] : null;
    if (esObjetoPlano(e) && typeof e.hash === 'string' && e.hash === sha256(b.prompt + RETOMA)) {
      retomadas.push(b.slide);
      return { slide: b.slide, prompt: b.prompt + RETOMA };
    }
    return b;
  });
  return { briefs: salida, retomadas };
}

// Fotos que se le muestran a GPT-4o: las pedidas en esta versión (image_briefs, nunca la portada ni el cierre que vienen
// de la propuesta), guardadas junto al plan según su manifest y que salieron en el último render (ni faltantes ni
// enlazadas afuera: el manifest conserva la entrada vieja de una foto que esta vez no salió, y esa no está en el
// documento). Solo archivos <lámina>.<ext> como los guarda el renderer: sin «..», barras ni archivos ocultos. ?v=
// cambia en cada render: la foto rehecha se guarda con el MISMO nombre y así nadie entrega una copia guardada.
function fotosParaRevisar(pedidas, manifest, images, uid, base, v) {
  const m = esObjetoPlano(manifest) ? manifest : {};
  const img = esObjetoPlano(images) ? images : {};
  const fuera = new Set([...(Array.isArray(img.missing) ? img.missing : []), ...(Array.isArray(img.kept_remote) ? img.kept_remote : [])].map(String));
  if (!/^[A-Za-z0-9_-]{6,64}$/.test(String(uid || '')) || !/^https?:\/\/[A-Za-z0-9.-]+(:\d+)?$/.test(String(base || ''))) return [];
  const vistas = new Set();
  return (Array.isArray(pedidas) ? pedidas : []).map(String).filter((s) => {
    if (vistas.has(s) || fuera.has(s) || !Object.prototype.hasOwnProperty.call(m, s)) return false;
    vistas.add(s);
    const e = m[s];
    return esObjetoPlano(e) && typeof e.file === 'string' && /^[A-Za-z0-9_-]+\.[A-Za-z0-9]{2,5}$/.test(e.file);
  }).map((s) => ({ slide: s, url: base + '/p/' + uid + '/img/' + m[s].file + '?v=' + (Number(v) || 0) }));
}

// UNA consulta con todas las fotos (la misma forma que «3 Final» de las propuestas): gpt-4o, temperatura 0, JSON.
function cuerpoRevision(fotos) {
  const contenido = [{ type: 'text', text: INSTRUCCION_TEXTO }];
  for (const f of fotos) {
    contenido.push({ type: 'text', text: 'Photo "' + f.slide + '":' });
    contenido.push({ type: 'image_url', image_url: { url: f.url, detail: 'high' } });
  }
  return { model: 'gpt-4o', temperature: 0, max_tokens: 200, response_format: { type: 'json_object' },
    messages: [{ role: 'user', content: contenido }] };
}

// Salida del nodo «Buscar texto en fotos» (fullResponse + neverError; {error} si se cortó la red). Devuelve las láminas
// con texto, sin repetidas y solo entre las que se le mostraron al modelo, o null con el motivo de la falla. Nunca lanza.
function leerRevision(r, mostradas) {
  const x = esObjetoPlano(r) ? r : {};
  if (x.statusCode !== 200) {
    const e = x.error;
    const msg = e && typeof e === 'object' ? e.message : e;
    return { con_texto: null, fallo: x.statusCode ? 'OpenAI respondió HTTP ' + x.statusCode : 'OpenAI no respondió' + (msg ? ': ' + sinUrlInterna(String(msg).slice(0, 200)) : '') };
  }
  try {
    const j = JSON.parse(x.body.choices[0].message.content);
    if (!esObjetoPlano(j) || !Array.isArray(j.con_texto)) throw new Error('sin con_texto');
    const l = Array.isArray(mostradas) ? mostradas : [];
    return { con_texto: [...new Set(j.con_texto.map(String))].filter((s) => l.includes(s)), fallo: '' };
  } catch (e) {
    return { con_texto: null, fallo: 'respuesta ilegible del modelo' };
  }
}

const RENDERER_BASE = "https://n8n-propuesta-renderer.kchiba.easypanel.host";
const MAX_RENDERS = 3;
// Arma UNA consulta a GPT-4o con las fotos nuevas del plan que quedaron guardadas (img/manifest.json del plan en el
